import{_ as t,c as r,a2 as a,o as s}from"./chunks/framework.CoXjB5sU.js";const u=JSON.parse('{"title":"System requirements","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/installation/system-requirements.md","filePath":"doc/guides/installation/system-requirements.md"}'),o={name:"doc/guides/installation/system-requirements.md"};function i(n,e,d,l,c,h){return s(),r("div",null,e[0]||(e[0]=[a('<h1 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h1><p>ioChem-BD is distributed as a self-contained bundle for <strong>Linux x64</strong>. Besides the ioChem-BD web applications, it includes Apache Tomcat, Apache Solr, the Caddy reverse proxy and Node.js, so the server only needs a few system packages.</p><h2 id="hardware-requirements" tabindex="-1">Hardware requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to &quot;Hardware requirements&quot;">​</a></h2><ul><li>A multicore CPU (4 cores, 2 GHz or better) so that several users can work at the same time without delays when calculations are uploaded and converted.</li><li>16 GB of RAM. By default the Tomcat server takes half of the server memory. You can change this with the <code>tomcatMaxHeap</code> installation parameter.</li><li>At least 500 GB of free disk space. The installation itself takes about 2 GB. The rest is for the uploaded calculations (Create and Browse assetstores) and the search indexes.</li></ul><h2 id="software-requirements" tabindex="-1">Software requirements <a class="header-anchor" href="#software-requirements" aria-label="Permalink to &quot;Software requirements&quot;">​</a></h2><ul><li>A 64-bit Linux distribution with systemd (tested on Fedora, RHEL/Rocky and Debian/Ubuntu).</li><li><strong>Java 21 JDK</strong>, the default <code>java</code> and <code>javac</code> on the <code>PATH</code>. Other Java versions are rejected by the installer.</li><li><strong>PostgreSQL 14 or newer</strong>, with the <em>postgresql-contrib</em> package (it provides the <code>pgcrypto</code> extension). The PostgreSQL client (<code>psql</code>) must be installed on the ioChem-BD server, even when the database runs on another host.</li><li><code>openssl</code>, <code>curl</code> and <code>ss</code> (<em>iproute</em> package).</li><li><code>setcap</code> (<em>libcap</em> package on RHEL/Fedora, <em>libcap2-bin</em> on Debian/Ubuntu), used once by <code>postinstall.sh</code> to let the proxy listen on ports 80 and 443.</li></ul><h2 id="network-requirements" tabindex="-1">Network requirements <a class="header-anchor" href="#network-requirements" aria-label="Permalink to &quot;Network requirements&quot;">​</a></h2><ul><li>A hostname for the service (e.g. <em>iochembd.university.edu</em>). Every module is published under <code>https://&lt;hostname&gt;/</code>: <code>/browse</code>, <code>/create</code> and <code>/cas</code>.</li><li>Ports <strong>80 and 443</strong> free on the server and reachable by the users. Port 80 only redirects to HTTPS. A Let&#39;s Encrypt certificate also needs it to be reachable from the Internet.</li><li>The server must resolve its own hostname, for example with a <code>127.0.0.1 &lt;hostname&gt;</code> line in <code>/etc/hosts</code>.</li></ul>',8)]))}const p=t(o,[["render",i]]);export{u as __pageData,p as default};
